let csrf="";const q=s=>document.querySelector(s),message=q("#message");async function request(path,options={}){options.headers={"Content-Type":"application/json",...(options.headers||{})};const response=await fetch(path,options);const body=[201,202,204].includes(response.status)&&!response.headers.get("content-type")?{}:await response.json();if(!response.ok)throw new Error(body.error||"Request failed");return body}function formJSON(form){return Object.fromEntries(new FormData(form))}async function updatePost(post,changes){await request(`/api/v1/posts/${post.id}`,{method:"PUT",headers:{"X-Watchpost-CSRF":csrf,"If-Match":String(post.version)},body:JSON.stringify({...post,...changes})});await load()}function card(title,detail){const node=document.createElement("article");node.className="post";const h=document.createElement("h3");h.textContent=title;const p=document.createElement("p");p.textContent=detail;node.append(h,p);return node}async function load(){const [postData,alertData,incidentData]=await Promise.all([request("/api/v1/posts"),request("/api/v1/alerts"),request("/api/v1/incidents")]);q("#posts").replaceChildren(...postData.posts.map(post=>{const node=card(post.name,`${post.kind} · ${post.id}`),maintenance=document.createElement("button"),archive=document.createElement("button");maintenance.textContent=post.maintenance?"End maintenance":"Start maintenance";maintenance.onclick=()=>updatePost(post,{maintenance:!post.maintenance});archive.textContent=post.archived?"Restore":"Archive";archive.onclick=()=>updatePost(post,{archived:!post.archived});node.append(maintenance,archive);return node}));q("#alerts").replaceChildren(...alertData.alerts.map(alert=>card(`${alert.severity}: ${alert.state}`,`${alert.post_id} · ${alert.rule_id}`)));q("#incidents").replaceChildren(...incidentData.incidents.map(incident=>card(incident.Title||incident.title,`${incident.Severity||incident.severity} · ${incident.Status||incident.status}`)))}q("#setup").onsubmit=async event=>{event.preventDefault();try{await request("/api/v1/setup",{method:"POST",body:JSON.stringify(formJSON(event.currentTarget))});alert("Administrator created. Sign in.")}catch(error){alert(error.message)}};q("#login").onsubmit=async event=>{event.preventDefault();try{const body=await request("/api/v1/login",{method:"POST",body:JSON.stringify(formJSON(event.currentTarget))});csrf=body.csrf_token;q(".auth").hidden=true;q("#workspace").hidden=false;await load()}catch(error){alert(error.message)}};q("#create").onsubmit=async event=>{event.preventDefault();const post=formJSON(event.currentTarget);post.labels={};try{await request("/api/v1/posts",{method:"POST",headers:{"X-Watchpost-CSRF":csrf},body:JSON.stringify(post)});event.currentTarget.reset();await load()}catch(error){message.textContent=error.message}};q("#check").onsubmit=async event=>{event.preventDefault();try{const result=await request("/api/v1/checks",{method:"POST",headers:{"X-Watchpost-CSRF":csrf},body:JSON.stringify(formJSON(event.currentTarget))});message.textContent=result.ok?`Check healthy in ${result.latency}`:`Check failed: ${result.failure}`}catch(error){message.textContent=error.message}};q("#incident").onsubmit=async event=>{event.preventDefault();const value=formJSON(event.currentTarget);value.alert_ids=[];try{await request("/api/v1/incidents",{method:"POST",headers:{"X-Watchpost-CSRF":csrf},body:JSON.stringify(value)});event.currentTarget.reset();await load()}catch(error){message.textContent=error.message}};
q("#history").onsubmit=async event=>{event.preventDefault();const values=formJSON(event.currentTarget),to=new Date(),from=new Date(to-3600000),signals=values.signals.split(",").map(v=>v.trim()).filter(Boolean),series=[];try{for(const signal of signals.slice(0,4)){const params=new URLSearchParams({signal,from:from.toISOString(),to:to.toISOString()});series.push({signal,points:(await request(`/api/v1/posts/${values.post}/history?${params}`)).points})}const all=series.flatMap(s=>s.points).filter(p=>p.value!==null),svg=q("#chart");svg.replaceChildren();if(!all.length){message.textContent="No numeric history in the last hour.";return}const numbers=all.map(p=>p.value),min=Math.min(...numbers),max=Math.max(...numbers),span=max-min||1,colors=["#78c7cb","#e4b85e","#e18176","#9caab5"];series.forEach((entry,index)=>{const numeric=entry.points.filter(p=>p.value!==null),line=document.createElementNS("http://www.w3.org/2000/svg","polyline");line.setAttribute("fill","none");line.setAttribute("stroke",colors[index]);line.setAttribute("stroke-width","3");line.setAttribute("points",numeric.map((p,i)=>`${20+(760*i/Math.max(1,numeric.length-1))},${200-(180*(p.value-min)/span)}`).join(" "));svg.append(line)});svg.hidden=false;const params=new URLSearchParams({signal:signals[0],from:from.toISOString(),to:to.toISOString(),format:"csv"}),link=q("#export");link.href=`/api/v1/posts/${values.post}/history?${params}`;link.hidden=false;link.textContent="Export first signal as CSV"}catch(error){message.textContent=error.message}};
